import { useEffect, useState } from 'react'
import fixture from '../fixtures/synthetic-tracer.json'
import { resolveSimulatedLaunch } from '../domain/launch-controller.mjs'
import { evaluateAcknowledgement } from '../domain/review-controller.mjs'
import { evaluateFollowUpDirection, evaluateT08Verification } from '../domain/direction-controller.mjs'
import { recordReferralRoute } from '../domain/referral-controller.mjs'
import { evaluateReceivingResponse } from '../domain/receiving-response-controller.mjs'
import { evaluateNextStepConfirmation, evaluateScopedClosure } from '../domain/next-step-controller.mjs'
import { EXCEPTION_PROFILES, evaluateExceptionResolution } from '../domain/exception-controller.mjs'
import { AI_DRAFTS, evaluateAiDraftReview } from '../domain/ai-draft-controller.mjs'
import { getAuditEntries } from '../domain/audit-trace.mjs'
import { APPROVED_SCREENS, resolveScreenId, type ScreenId } from './screen-contract'
import { JourneyRail, WorkflowStatus } from '../components/WorkflowContext'

function screenFromHash(): ScreenId { return resolveScreenId(window.location.hash.replace('#', '') || 'SCR-01') }
function navigateTo(screenId: ScreenId) { window.location.hash = screenId }

function Launch({ status, onLaunch }: { status: 'ready' | 'loading'; onLaunch: (outcome?: 'authorised' | 'unavailable') => void }) {
  const loading = status === 'loading'
  return <section className="content-card"><p className="eyebrow">SCR-01 · COS-601 · simulated SMART launch</p><h2>Access status before protected context</h2><p>Clinic physician: Synthetic Clinic Physician · SYN-PRAC-3001. This simulated launch is read-only.</p><WorkflowStatus state={loading ? 'Launch, authorisation and retrieval in progress' : 'Ready — no protected context retrieved'} owner="Clinic physician; Product/platform administrator supports access conditions" next={loading ? 'Wait for the simulated access outcome' : 'Start authorised simulated launch'} /><div className="action-group"><button className="primary-action" disabled={loading} type="button" onClick={() => onLaunch()}>{loading ? 'Checking simulated access…' : 'Start authorised simulated launch'}</button><button className="secondary-action" disabled={loading} type="button" onClick={() => onLaunch('unavailable')}>Show represented unavailable access condition</button></div></section>
}

function Workspace({ authorised, onException }: { authorised: boolean; onException: () => void }) {
  if (!authorised) return <section className="content-card"><p className="eyebrow">SCR-02 · protected context gate</p><h2>Authorised context is required</h2><p>The workspace stays hidden until simulated launch and verified linkage pass.</p><button className="secondary-action" type="button" onClick={onException}>View safe access-recovery route</button></section>
  const report = fixture.diagnosticReports[0]
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-02 · COS-602 · active synthetic episode</p><h2>Asha Mehta <span>· SYNTHETIC CASE</span></h2><p>Episode SYN-EP-8001 · Encounter SYN-ENC-2001 · verified linkage</p></div><span className="state-badge">Diagnostic Completed</span></header><div className="screen-grid"><div><WorkflowStatus state="Diagnostic Completed" owner="Care Coordinator" next="Await current report availability and assigned review task" ageDue="No review task is assigned yet; due context is unavailable until assignment." /><section className="milestones"><h3>Workflow evidence</h3><ol><li><strong>Order created</strong><span>ServiceRequest SYN-SR-4001 · read-only source record</span></li><li><strong>Diagnostic completed</strong><span>Operational completion evidence remains separate from result availability</span></li><li><strong>Result availability</strong><span>{report.id} v{report.version} · shown only after fixture-specific T04 validation</span></li></ol></section><div className="status-panel"><strong>Assigned review task is not yet available</strong><span>No acknowledgement, direction, referral, identity reconciliation or closure action is available here.</span></div></div><JourneyRail phase="Diagnostic progress" next="Result availability and clinician assignment remain separate evidence checks." /></div></section>
}

function ReviewScreen({ onException }: { onException: (condition: string) => void }) {
  const [acknowledgedAt, setAcknowledgedAt] = useState<string | null>(null)
  const assignment = fixture.reviewAssignment
  const report = fixture.diagnosticReports.find((item) => item.version === assignment.reportVersion)!
  const outcome = evaluateAcknowledgement(fixture, { actorRef: assignment.assignedTo, reportVersion: assignment.reportVersion, currentState: assignment.state, acknowledgementId: 'SYN-ACK-602-01' })
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-03 · COS-603 · result review</p><h2>Current report requires clinician acknowledgement</h2><p>Asha Mehta · SYNTHETIC CASE · source report remains read-only</p></div><span className="state-badge">{acknowledgedAt ? 'Result Acknowledged' : assignment.state}</span></header><div className="screen-grid"><div><WorkflowStatus state={acknowledgedAt ? 'Result Acknowledged' : assignment.state} owner="Synthetic Clinic Physician · assigned reviewer" next={acknowledgedAt ? 'Follow-up Decision Required — implemented in COS-604' : 'Review the current source report and explicitly acknowledge'} ageDue={`Assigned task due ${assignment.dueAt}`} /><section className="evidence-panel"><p className="panel-label">Read-only source report</p><h3>{report.id} · current v{report.version}</h3><dl><div><dt>Source status</dt><dd>{report.status} · current version</dd></div><div><dt>Order link</dt><dd>{report.basedOn}</dd></div><div><dt>Supporting evidence</dt><dd>{report.resultRefs.join(', ')}</dd></div></dl></section>{acknowledgedAt ? <div className="status-panel" role="status"><strong>Acknowledgement recorded for current report version {report.version}</strong><span>Actor: Synthetic Clinic Physician · recorded at {acknowledgedAt} · EVT-10 result.acknowledgement.recorded.</span></div> : <div className="action-group"><button className="primary-action" type="button" onClick={() => outcome.allowed ? setAcknowledgedAt('2026-07-26T10:00:00+05:30') : onException(outcome.reason)}>Acknowledge current report version</button><button className="secondary-action" type="button" onClick={() => onException('Result Incomplete')}>Show incomplete-result safe route</button></div>}</div><JourneyRail phase="Clinical review" next="Only the assigned Clinic physician may acknowledge the current version." /></div></section>
}

type DirectionSuccess = Extract<ReturnType<typeof evaluateFollowUpDirection>, { allowed: true }>

function OldDirectionScreen({ onException }: { onException: (condition: string) => void }) {
  const [selectedDirection, setSelectedDirection] = useState('')
  const [evidenceReference, setEvidenceReference] = useState('')
  const [result, setResult] = useState<DirectionSuccess | null>(null)
  function recordDirection() { const outcome = evaluateFollowUpDirection({ actorRole: 'Clinic physician', currentState: 'Follow-up Decision Required', reportVersion: '2', selectedDirection, evidenceReference, directionId: 'SYN-DIR-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setResult(outcome) }
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-04 · COS-604 · human-owned follow-up direction</p><h2>Record a follow-up direction</h2><p>Asha Mehta · SYNTHETIC CASE · acknowledged report SYN-DR-6001 v2</p></div><span className="state-badge">{result?.stateAfter ?? 'Follow-up Decision Required'}</span></header><div className="screen-grid"><div><WorkflowStatus state={result?.stateAfter ?? 'Follow-up Decision Required'} owner="Synthetic Clinic Physician · clinical direction owner" next={result?.nextAction ?? 'Select one direction and record its evidence'} /><section className="evidence-panel"><p className="panel-label">Human decision boundary</p><h3>Clinic physician decision</h3><p>ContinuumOS records the selected direction and evidence. It does not recommend, rank or preselect a care direction.</p><fieldset className="direction-options" disabled={Boolean(result)}><legend>Select one approved direction</legend>{['clinic management', 'day-care referral', 'hospital escalation'].map((direction) => <label key={direction}><input checked={selectedDirection === direction} name="direction" type="radio" onChange={() => setSelectedDirection(direction)} />{direction}</label>)}</fieldset><label className="evidence-input">Direction rationale / evidence reference<input value={evidenceReference} onChange={(event) => setEvidenceReference(event.target.value)} placeholder="For example: SYN-DR-6001 v2" disabled={Boolean(result)} /></label>{result ? <div className="status-panel" role="status"><strong>Direction recorded: {selectedDirection}</strong><span>Actor: Synthetic Clinic Physician · report v2 · EVT-11. {result.requiresCoordinatorVerification ? 'Clinic-management T08 verification remains pending with the Care Coordinator; no confirmation is available here.' : result.nextAction}</span></div> : <div className="action-group"><button className="primary-action" type="button" onClick={recordDirection}>Record follow-up direction</button><button className="secondary-action" type="button" onClick={() => onException('Current report version requires review')}>Show stale-version safe route</button></div>}</section></div><JourneyRail phase="Human direction" next={result?.nextAction ?? 'A human Clinic physician must choose and evidence the next direction.'} /></div></section>
}

function ReferralScreen({ onException }: { onException: (condition: string) => void }) {
  const [destination, setDestination] = useState('')
  const [requiredFieldsComplete, setRequiredFieldsComplete] = useState(false)
  const [clinicalContentApplicable, setClinicalContentApplicable] = useState(true)
  const [clinicalApprovalId, setClinicalApprovalId] = useState('')
  const [routed, setRouted] = useState(false)
  const packageInput = { actorRole: 'Referral Coordinator', currentState: 'Referral Created', direction: 'day-care referral', reportVersion: '2', packageId: 'SYN-RP-1001 v1', destination, requiredFieldsComplete, coordinatorApprovalId: 'SYN-RC-1001', clinicalContentApplicable, clinicalApprovalId }
  const readiness = recordReferralRoute({ ...packageInput, alreadyRouted: false, sendOutcome: 'sent' })
  const readinessMessage = readiness.allowed ? 'Referral Coordinator approval: SYN-RC-1001. Route records a send attempt only; it is not delivery or receiving acceptance.' : readiness.reason
  function routePackage() { const outcome = recordReferralRoute({ ...packageInput, alreadyRouted: routed, sendOutcome: 'sent' }); if ('reason' in outcome) { onException(outcome.reason); return }; setRouted(true) }
  function showSendFailure() { const outcome = recordReferralRoute({ ...packageInput, alreadyRouted: false, sendOutcome: 'failed' }); if ('reason' in outcome) onException(outcome.reason) }
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-05 · COS-605 · referral handoff preparation</p><h2>Prepare a human-approved handoff</h2><p>Asha Mehta · SYNTHETIC CASE · direction: day-care referral · report SYN-DR-6001 v2</p></div><span className="state-badge">Referral Created</span></header><div className="screen-grid"><div><WorkflowStatus state="Referral Created" owner="Synthetic Referral Coordinator · operational package owner" next={routed ? 'Await receiving-team response. No acceptance has been recorded.' : 'Complete and explicitly route the human-approved package'} ageDue="Package route is pending; receiving-team workflow is not implemented in COS-605." /><section className="evidence-panel"><p className="panel-label">Source-linked context · read only</p><h3>Approved human direction</h3><dl><div><dt>Direction</dt><dd>Day-care referral · Clinic physician evidence: SYN-DIR-602-01</dd></div><div><dt>Current acknowledged report</dt><dd>SYN-DR-6001 v2 · source record remains read-only</dd></div><div><dt>Package version</dt><dd>SYN-RP-1001 v1 · internal operational artefact</dd></div></dl></section><section className="evidence-panel referral-panel"><p className="panel-label">Handoff package and routing gate</p><h3>Referral Coordinator review</h3><label className="evidence-input">Destination<input value={destination} onChange={(event) => setDestination(event.target.value)} disabled={routed} placeholder="Enter receiving destination" /></label><label className="check-label"><input checked={requiredFieldsComplete} disabled={routed} type="checkbox" onChange={(event) => setRequiredFieldsComplete(event.target.checked)} />Required package fields are complete and reviewed</label><label className="check-label"><input checked={clinicalContentApplicable} disabled={routed} type="checkbox" onChange={(event) => setClinicalContentApplicable(event.target.checked)} />Clinical content approval is applicable</label>{clinicalContentApplicable && <label className="evidence-input">Clinic physician clinical-content approval<input value={clinicalApprovalId} onChange={(event) => setClinicalApprovalId(event.target.value)} disabled={routed} placeholder="Enter approval evidence ID" /></label>}<div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready for explicit human routing' : 'Routing remains blocked'}</strong><span>{readinessMessage}</span></div>{routed ? <div className="status-panel" role="status"><strong>Routing evidence recorded</strong><span>EVT-12 package and EVT-13 send attempt · sender: Synthetic Referral Coordinator · destination: {destination}. State remains Referral Created pending a receiving-team response.</span></div> : <div className="action-group"><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={routePackage}>Route approved handoff</button><button className="secondary-action" type="button" onClick={showSendFailure}>Show represented send failure</button></div>}</section></div><JourneyRail phase="Handoff preparation" next="An explicit Referral Coordinator route is required before the receiving team can respond." /></div></section>
}

function ReceivingResponseScreen({ onException }: { onException: (condition: string) => void }) {
  const [decisionActor, setDecisionActor] = useState('')
  const [recordingActorRole, setRecordingActorRole] = useState('Receiving team')
  const [recordingSource, setRecordingSource] = useState('')
  const [response, setResponse] = useState('')
  const [destination, setDestination] = useState('')
  const [timeframe, setTimeframe] = useState('')
  const [rejectionReason, setRejectionReason] = useState('')
  const [confirmed, setConfirmed] = useState(false)
  const [result, setResult] = useState<Extract<ReturnType<typeof evaluateReceivingResponse>, { allowed: true }> | null>(null)
  const responseInput = { currentState: 'Referral Created', packageId: 'SYN-RP-1001 v1', sendReference: 'SYN-SEND-1001', decisionActorRole: 'Receiving team', decisionActor, recordingActorRole, recordingSource, response, destination, timeframe, rejectionReason, confirmationId: confirmed ? 'SYN-CONFIRM-1002' : '', responseId: 'SYN-RESP-1001', alreadyRecorded: Boolean(result) }
  const readiness = evaluateReceivingResponse({ ...responseInput, alreadyRecorded: false })
  function recordResponse() { const outcome = evaluateReceivingResponse(responseInput); if ('reason' in outcome) { onException(outcome.reason); return }; setResult(outcome) }
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-06 · COS-606 · receiving response</p><h2>Record the receiving team’s response</h2><p>Asha Mehta · SYNTHETIC CASE · routed package SYN-RP-1001 v1</p></div><span className="state-badge">{result?.stateAfter ?? 'Referral Created'}</span></header><div className="screen-grid"><div><WorkflowStatus state={result?.stateAfter ?? 'Referral Created'} owner={result?.stateAfter === 'Referral Rejected' ? 'Clinic physician · new direction owner' : 'Synthetic receiving team · response owner'} next={result?.nextAction ?? 'Record an explicit receiving-team acceptance or rejection'} ageDue="Routed package awaiting response; sending the package did not establish acceptance." /><section className="evidence-panel"><p className="panel-label">Routed package evidence · read only</p><h3>Package sent for receiving-team review</h3><dl><div><dt>Package / send reference</dt><dd>SYN-RP-1001 v1 · SYN-SEND-1001</dd></div><div><dt>Routed destination</dt><dd>Synthetic Day-care Unit</dd></div><div><dt>Boundary</dt><dd>Package send is not receiving acceptance or specialist review.</dd></div></dl></section><section className="evidence-panel receiving-panel"><p className="panel-label">Human receiving-team decision</p><h3>Response evidence</h3><label className="evidence-input">Receiving-team decision actor<input disabled={Boolean(result)} value={decisionActor} onChange={(event) => setDecisionActor(event.target.value)} placeholder="Enter receiving-team decision actor" /></label><label className="evidence-input">Recording actor<select disabled={Boolean(result)} value={recordingActorRole} onChange={(event) => setRecordingActorRole(event.target.value)}><option value="Receiving team">Receiving team</option><option value="Referral Coordinator">Referral Coordinator</option></select></label>{recordingActorRole === 'Referral Coordinator' && <label className="evidence-input">Received-response source<input disabled={Boolean(result)} value={recordingSource} onChange={(event) => setRecordingSource(event.target.value)} placeholder="Enter the receiving-team response source" /></label>}<fieldset className="response-options" disabled={Boolean(result)}><legend>Select the formal receiving-team response</legend><label><input checked={response === 'accept'} name="response" type="radio" onChange={() => setResponse('accept')} />Accept</label><label><input checked={response === 'reject'} name="response" type="radio" onChange={() => setResponse('reject')} />Reject</label></fieldset>{response === 'accept' && <div className="response-grid"><label>Receiving destination<input value={destination} onChange={(event) => setDestination(event.target.value)} disabled={Boolean(result)} /></label><label>Acceptance timeframe<input value={timeframe} onChange={(event) => setTimeframe(event.target.value)} disabled={Boolean(result)} /></label></div>}{response === 'reject' && <label className="evidence-input">Rejection reason<input value={rejectionReason} onChange={(event) => setRejectionReason(event.target.value)} disabled={Boolean(result)} /></label>}<label className="check-label confirmation"><input checked={confirmed} disabled={Boolean(result)} type="checkbox" onChange={(event) => setConfirmed(event.target.checked)} />I confirm the selected response, receiving-team decision actor and response evidence.</label><div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready for explicit response recording' : 'Response remains pending'}</strong><span>{readiness.allowed ? 'EVT-14 will record the human response. Acceptance does not confirm the next step; rejection does not create an alternative referral.' : readiness.reason}</span></div>{result ? <div className="status-panel" role="status"><strong>Receiving response recorded: {result.stateAfter}</strong><span>EVT-14 · decision actor: {decisionActor} · recording actor: {recordingActorRole}. {result.nextAction}</span></div> : <button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordResponse}>Record receiving response</button>}</section></div><JourneyRail phase="Receiving response" next="Confirm accountable follow-up only after the applicable evidence exists." /></div></section>
}

function AiDraftReviewScreen({ onReturn }: { onReturn: (screenId: ScreenId) => void }) {
  const [capabilityId, setCapabilityId] = useState('AI-01')
  const [reviewerRole, setReviewerRole] = useState('')
  const [draftStatus, setDraftStatus] = useState('generated')
  const [disposition, setDisposition] = useState('')
  const [correctionNote, setCorrectionNote] = useState('')
  const [result, setResult] = useState<Extract<ReturnType<typeof evaluateAiDraftReview>, { allowed: true }> | null>(null)
  const draft = AI_DRAFTS[capabilityId]
  const manualRoute = capabilityId === 'AI-01' ? 'SCR-03' : 'SCR-05'
  const reviewInput = { capabilityId, reviewerRole, reportVersion: '2', directionEvidence: capabilityId === 'AI-02' ? 'SYN-DIR-602-01' : '', draftStatus, sourceLinksComplete: true, disposition, correctionNote }
  const readiness = evaluateAiDraftReview(reviewInput)
  function changeCapability(nextCapability: string) { setCapabilityId(nextCapability); setReviewerRole(''); setDraftStatus('generated'); setDisposition(''); setCorrectionNote(''); setResult(null) }
  function recordDisposition() { const outcome = evaluateAiDraftReview(reviewInput); if ('reason' in outcome) return; setResult(outcome) }
  return <section className="workspace-screen ai-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-08 · COS-608 · optional AI draft review</p><h2>Review an assistive draft, then decide manually</h2><p>Asha Mehta · SYNTHETIC CASE · AI output is not source truth or a workflow decision</p></div><span className="state-badge">No canonical state change</span></header><div className="screen-grid"><div><WorkflowStatus state="Human workflow remains active" owner="Authorised human reviewer" next={result ? `Return to ${result.manualRoute} and continue manually` : 'Review provenance, uncertainty and disposition before relying on the optional draft'} ageDue="The AI assist is optional. Its failure cannot block source-based work." /><section className="evidence-panel"><p className="panel-label">Assist selection</p><h3>Choose the approved synthetic assist</h3><fieldset className="response-options"><legend>Capability</legend><label><input checked={capabilityId === 'AI-01'} name="capability" type="radio" onChange={() => changeCapability('AI-01')} />AI-01 · source-linked orientation draft</label><label><input checked={capabilityId === 'AI-02'} name="capability" type="radio" onChange={() => changeCapability('AI-02')} />AI-02 · post-approval handoff draft</label></fieldset><p className="ai-boundary">AI may draft orientation or operational context only. It cannot diagnose, acknowledge, choose direction, approve, route, accept, reject, confirm or close work.</p></section><section className="evidence-panel ai-draft-panel"><p className="panel-label">AI-generated draft · requires human review</p><h3>{draft.draftId} · {draftStatus}</h3><p>{draft.text}</p><dl><div><dt>Generated time</dt><dd>{draft.generatedAt}</dd></div><div><dt>Source links / versions</dt><dd>{draft.sourceLinks.join(' · ')}</dd></div><div><dt>Uncertainty</dt><dd>{draft.uncertainty}</dd></div><div><dt>Workflow boundary</dt><dd>Draft review records EVT-20 only; no workflow state changes.</dd></div></dl><label className="evidence-input">Authorised reviewer role<select value={reviewerRole} onChange={(event) => setReviewerRole(event.target.value)}><option value="">Select reviewer role</option>{capabilityId === 'AI-01' ? <><option value="Clinic physician">Clinic physician</option><option value="Care Coordinator">Care Coordinator</option></> : <option value="Referral Coordinator">Referral Coordinator</option>}</select></label><fieldset className="response-options"><legend>Represented draft status</legend><label><input checked={draftStatus === 'generated'} name="draft-status" type="radio" onChange={() => setDraftStatus('generated')} />Generated and source-linked</label><label><input checked={draftStatus === 'unavailable'} name="draft-status" type="radio" onChange={() => setDraftStatus('unavailable')} />Unavailable</label><label><input checked={draftStatus === 'stale'} name="draft-status" type="radio" onChange={() => setDraftStatus('stale')} />Stale source/input</label></fieldset><label className="evidence-input">Human disposition<select value={disposition} onChange={(event) => setDisposition(event.target.value)}><option value="">Select disposition</option>{capabilityId === 'AI-01' && <option value="accepted_for_orientation">Accept for orientation</option>}{capabilityId === 'AI-02' && <option value="accepted_for_use">Accept for use</option>}<option value="corrected">Correct</option><option value="rejected">Reject</option><option value="discarded">Discard</option></select></label>{disposition === 'corrected' && <label className="evidence-input">Correction note<input value={correctionNote} onChange={(event) => setCorrectionNote(event.target.value)} placeholder="Record the human correction" /></label>}<div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to record human disposition' : 'Manual workflow remains available'}</strong><span>{readiness.allowed ? 'EVT-20 will record provenance and disposition only. The human must continue through the normal workflow.' : readiness.reason}</span></div>{result ? <div className="status-panel" role="status"><strong>Human disposition recorded: {result.disposition}</strong><span>{result.auditEvent} · no canonical state changed. Use the manual route to continue.</span><button className="secondary-action" type="button" onClick={() => onReturn(result.manualRoute as ScreenId)}>Return to calling workflow</button></div> : <div className="action-group"><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordDisposition}>Record human disposition</button><button className="secondary-action" type="button" onClick={() => onReturn(manualRoute as ScreenId)}>Continue manually without AI</button></div>}</section></div><JourneyRail phase="Optional assistance" next="Manual source-based workflow remains available regardless of AI output." /></div></section>
}

function AuditTraceScreen() {
  const [category, setCategory] = useState('all')
  const entries = getAuditEntries(category)
  return <section className="workspace-screen audit-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-09 · COS-609 · audit and trace</p><h2>Review attributable workflow evidence</h2><p>Asha Mehta · SYNTHETIC CASE · append-oriented local trace · read only</p></div><span className="state-badge">No workflow action available</span></header><WorkflowStatus state="Audit evidence available" owner="Governance and authorised operational reviewers" next="Review evidence; missing or failed evidence remains a visible defect" ageDue="This screen cannot edit history, correct evidence or advance workflow." /><section className="evidence-panel audit-controls"><p className="panel-label">Read-only trace filter</p><label className="evidence-input">Evidence category<select value={category} onChange={(event) => setCategory(event.target.value)}><option value="all">All evidence</option><option value="source">Source evidence</option><option value="human decision">Human decisions</option><option value="workflow">Workflow evidence</option><option value="exception">Exceptions</option><option value="recovery">Recovery</option><option value="AI disposition">AI dispositions</option></select></label><p>Each row retains event/outcome, actor or source, timestamp, and linked source/version context. AI, exception and human evidence remain distinct.</p></section><div className="audit-table-wrap"><table><caption>Chronological synthetic audit evidence</caption><thead><tr><th scope="col">Time</th><th scope="col">Event / outcome</th><th scope="col">Actor or source</th><th scope="col">Reference</th></tr></thead><tbody>{entries.map((entry) => <tr key={entry.id}><td>{entry.timestamp}</td><td><strong>{entry.event}</strong><span>{entry.outcome} · {entry.category}</span></td><td>{entry.actor}</td><td>{entry.reference}</td></tr>)}</tbody></table></div><div className="status-panel"><strong>Audit trace is read-only</strong><span>Corrections and recoveries must append linked evidence; a failed action is never shown as success. This screen contains no destructive correction or workflow controls.</span></div></section>
}

function NextStepConfirmationScreen({ onException }: { onException: (condition: string) => void }) {
  const [evidence, setEvidence] = useState({ owner: '', destination: '', timeframe: '', communicationApproval: '', authorisedSender: '', channel: '', deliveryEvidence: '', explicitConfirmationEvidence: '' })
  const [confirmed, setConfirmed] = useState(false)
  const [closed, setClosed] = useState(false)
  const updateEvidence = (field: keyof typeof evidence, value: string) => setEvidence((current) => ({ ...current, [field]: value }))
  const sharedInput = { actorRole: 'Care Coordinator', reportVersion: '2', directionEvidence: 'SYN-DIR-602-01', handoffStatus: 'completed', receivingResponse: 'accepted', explicitConfirmationRequired: true, hasSafetyBlockingException: false, ...evidence }
  const confirmationReadiness = evaluateNextStepConfirmation({ ...sharedInput, currentState: 'Referral Accepted', confirmationId: 'SYN-CONFIRM-1003', alreadyConfirmed: false })
  const closureReadiness = evaluateScopedClosure({ ...sharedInput, currentState: 'Next Step Confirmed', closureId: 'SYN-CLOSE-1001', closureEvidenceVersion: 'SYN-CLOSURE-EVIDENCE-v1', closer: 'Synthetic Care Coordinator', closureTime: '2026-07-26T14:00:00+05:30', alreadyClosed: false })
  function recordConfirmation() { const outcome = evaluateNextStepConfirmation({ ...sharedInput, currentState: 'Referral Accepted', confirmationId: 'SYN-CONFIRM-1003', alreadyConfirmed: confirmed }); if ('reason' in outcome) { onException(outcome.reason); return }; setConfirmed(true) }
  function recordClosure() { const outcome = evaluateScopedClosure({ ...sharedInput, currentState: 'Next Step Confirmed', closureId: 'SYN-CLOSE-1001', closureEvidenceVersion: 'SYN-CLOSURE-EVIDENCE-v1', closer: 'Synthetic Care Coordinator', closureTime: '2026-07-26T14:00:00+05:30', alreadyClosed: closed }); if ('reason' in outcome) { onException(outcome.reason); return }; setClosed(true) }
  const state = closed ? 'Episode Completed' : confirmed ? 'Next Step Confirmed' : 'Referral Accepted'
  return <section className="workspace-screen closure-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-10 · COS-610 · next-step confirmation and scoped closure</p><h2>Confirm the next step, then close the diagnostic workflow separately</h2><p>Asha Mehta · SYNTHETIC CASE · day-care referral · current report SYN-DR-6001 v2</p></div><span className="state-badge">{state}</span></header><div className="screen-grid"><div><WorkflowStatus state={state} owner="Care Coordinator records verification and closure evidence" next={closed ? 'No further diagnostic-closure action is available.' : confirmed ? 'Review closure evidence and record scoped completion separately.' : 'Verify applicable human-owned evidence before recording Next Step Confirmed.'} ageDue="No automatic confirmation or closure is available." /><section className="evidence-panel"><p className="panel-label">Human direction and referral response · read only</p><h3>Required route evidence</h3><dl><div><dt>Human direction</dt><dd>Day-care referral · Clinic physician · SYN-DIR-602-01 · current report v2</dd></div><div><dt>Handoff / response</dt><dd>Completed handoff SYN-RP-1001 v1 · receiving-team acceptance EVT-14</dd></div><div><dt>Exception check</dt><dd>No safety-blocking exception represented for this local scenario.</dd></div></dl></section><section className="evidence-panel closure-evidence-panel"><p className="panel-label">Care Coordinator verification</p><h3>Evidence required before the active action</h3><div className="confirmation-grid"><label>Next-step owner<input disabled={confirmed || closed} value={evidence.owner} onChange={(event) => updateEvidence('owner', event.target.value)} /></label><label>Destination / team<input disabled={confirmed || closed} value={evidence.destination} onChange={(event) => updateEvidence('destination', event.target.value)} /></label><label>Timeframe<input disabled={confirmed || closed} value={evidence.timeframe} onChange={(event) => updateEvidence('timeframe', event.target.value)} /></label><label>Approved communication reference<input disabled={confirmed || closed} value={evidence.communicationApproval} onChange={(event) => updateEvidence('communicationApproval', event.target.value)} /></label><label>Authorised sender<input disabled={confirmed || closed} value={evidence.authorisedSender} onChange={(event) => updateEvidence('authorisedSender', event.target.value)} /></label><label>Channel<input disabled={confirmed || closed} value={evidence.channel} onChange={(event) => updateEvidence('channel', event.target.value)} /></label><label>Delivery evidence · EVT-17<input disabled={confirmed || closed} value={evidence.deliveryEvidence} onChange={(event) => updateEvidence('deliveryEvidence', event.target.value)} /></label><label>Explicit patient/caregiver confirmation · EVT-18<input disabled={confirmed || closed} value={evidence.explicitConfirmationEvidence} onChange={(event) => updateEvidence('explicitConfirmationEvidence', event.target.value)} /></label></div><p className="closure-boundary">Delivery and explicit confirmation are separate evidence. The Care Coordinator verifies them but cannot supply the clinical direction, receiving-team response, or patient confirmation.</p>{!confirmed ? <><div className={confirmationReadiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{confirmationReadiness.allowed ? 'Ready for human-recorded next-step confirmation' : 'Next-step confirmation remains blocked'}</strong><span>{confirmationReadiness.allowed ? 'Care Coordinator, action, evidence and recorded timestamp are shown before EVT-16 is recorded.' : confirmationReadiness.reason}</span></div><div className="action-group"><button className="primary-action" disabled={!confirmationReadiness.allowed} type="button" onClick={recordConfirmation}>Record Next Step Confirmed</button><button className="secondary-action" type="button" onClick={() => onException('Missing handoff or confirmation evidence')}>Show safe exception route</button></div></> : <div className="status-panel" role="status"><strong>Next Step Confirmed recorded</strong><span>EVT-16 · Care Coordinator · synthetic timestamp 2026-07-26T14:00:00+05:30. This confirmation does not close the diagnostic workflow.</span></div>}{confirmed && !closed && <div className="closure-action"><h3>Scoped closure</h3><p>Closure is a second human-owned action. It is not inferred from the confirmation, delivery or any AI activity.</p><div className={closureReadiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{closureReadiness.allowed ? 'Ready for scoped diagnostic-closure workflow completion' : 'Scoped closure remains blocked'}</strong><span>{closureReadiness.allowed ? 'The Care Coordinator may now record EVT-22 with the complete applicable evidence.' : closureReadiness.reason}</span></div><button className="primary-action" disabled={!closureReadiness.allowed} type="button" onClick={recordClosure}>Record scoped Episode Completed</button></div>}{closed && <div className="status-panel" role="status"><strong>Episode Completed · diagnostic-closure workflow completion</strong><span>EVT-22 · Care Coordinator · synthetic timestamp 2026-07-26T14:00:00+05:30. This does not claim that all care is complete.</span></div>}</section></div><JourneyRail phase="Confirmed next step" next={closed ? 'Diagnostic-closure workflow complete; broader care continues outside this scope.' : 'Complete the applicable evidence checks before the next separate human action.'} /></div></section>
}

function ExceptionScreen({ detail, onReturn }: { detail: Extract<ReturnType<typeof resolveSimulatedLaunch>, { kind: 'exception' }> | null; onReturn: (state: string) => void }) {
  const initialId = EXCEPTION_PROFILES.find((item) => item.condition === detail?.condition)?.id ?? 'result-incomplete'
  const [selectedId, setSelectedId] = useState(initialId)
  const [actorRole, setActorRole] = useState('')
  const [resolutionEvidence, setResolutionEvidence] = useState('')
  const [verificationOutcome, setVerificationOutcome] = useState('')
  const [resolution, setResolution] = useState<Extract<ReturnType<typeof evaluateExceptionResolution>, { allowed: true }> | null>(null)
  const profile = EXCEPTION_PROFILES.find((item) => item.id === selectedId)!
  const readiness = evaluateExceptionResolution({ exceptionId: selectedId, actorRole, resolutionEvidence, verificationOutcome, alreadyResolved: false })
  function selectException(id: string) { setSelectedId(id); setActorRole(''); setResolutionEvidence(''); setVerificationOutcome(''); setResolution(null) }
  function recordResolution() { const outcome = evaluateExceptionResolution({ exceptionId: selectedId, actorRole, resolutionEvidence, verificationOutcome, alreadyResolved: Boolean(resolution) }); if ('reason' in outcome) return; setResolution(outcome) }
  return <section className="workspace-screen exception-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-07 · COS-607 · exception queue and detail</p><h2>Resolve exception work safely</h2><p>Asha Mehta · SYNTHETIC CASE · workflow remains paused until verified recovery</p></div><span className="state-badge">{resolution ? 'Resolution recorded' : profile.condition}</span></header><div className="screen-grid"><div><WorkflowStatus state={resolution ? profile.lastVerifiedState : 'Exception open'} owner={profile.owner} next={resolution?.nextAction ?? profile.safeAction} ageDue="No automatic progression is available while this exception remains open." /><section className="exception-queue" aria-label="Open exception work"><p className="panel-label">Open exception work</p><h3>Select a represented condition</h3><div>{EXCEPTION_PROFILES.map((item) => <button aria-pressed={item.id === selectedId} className={item.id === selectedId ? 'exception-item selected' : 'exception-item'} key={item.id} type="button" onClick={() => selectException(item.id)}><strong>{item.condition}</strong><span>{item.owner}</span></button>)}</div></section><section className="evidence-panel exception-detail-panel"><p className="panel-label">Exception detail · {profile.auditEvent}</p><h3>{profile.condition}</h3><dl><div><dt>Affected work</dt><dd>{profile.affectedWork}</dd></div><div><dt>Accountable owner</dt><dd>{profile.owner}</dd></div><div><dt>Prohibited action</dt><dd>{profile.prohibitedAction}</dd></div><div><dt>Safe action</dt><dd>{profile.safeAction}</dd></div><div><dt>Safe-return condition</dt><dd>{profile.safeReturn}</dd></div></dl>{resolution ? <div className="status-panel" role="status"><strong>Verified resolution recorded</strong><span>{resolution.auditEvent} · return state: {resolution.stateAfter}. The original human action, if needed, must be repeated only after return.</span><button className="secondary-action" type="button" onClick={() => onReturn(resolution.stateAfter)}>Return to last verified work</button></div> : <><label className="evidence-input">Accountable resolution role<select value={actorRole} onChange={(event) => setActorRole(event.target.value)}><option value="">Select accountable role</option>{[...new Set(EXCEPTION_PROFILES.map((item) => item.actorRole))].map((role) => <option key={role} value={role}>{role}</option>)}</select></label><label className="evidence-input">Verified resolution evidence<input value={resolutionEvidence} onChange={(event) => setResolutionEvidence(event.target.value)} placeholder="Enter source verification or recovery evidence ID" /></label><fieldset className="response-options"><legend>Verification outcome</legend><label><input checked={verificationOutcome === 'verified'} name="verification" type="radio" onChange={() => setVerificationOutcome('verified')} />Verified resolution</label><label><input checked={verificationOutcome === 'failed'} name="verification" type="radio" onChange={() => setVerificationOutcome('failed')} />Resolution failed or remains unresolved</label></fieldset><div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to record verified resolution' : 'Exception remains open'}</strong><span>{readiness.allowed ? 'EVT-21 will record recovery evidence only. It does not recreate a clinical, referral, financial or closure action.' : readiness.reason}</span></div><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordResolution}>Record verified resolution</button></>}</section></div><JourneyRail phase="Journey paused: needs review" next="Return only to the last verified step after accountable human resolution." /></div></section>
}

function DirectionScreen({ onException }: { onException: (condition: string) => void }) {
  const [selectedDirection, setSelectedDirection] = useState('')
  const [evidenceReference, setEvidenceReference] = useState('')
  const [result, setResult] = useState<DirectionSuccess | null>(null)
  const [t08Confirmed, setT08Confirmed] = useState(false)
  const [t08Evidence, setT08Evidence] = useState({ owner: '', timeframe: '', nextTask: '', communicationEvidence: '' })
  const updateT08 = (field: keyof typeof t08Evidence, value: string) => setT08Evidence((current) => ({ ...current, [field]: value }))
  function recordDirection() { const outcome = evaluateFollowUpDirection({ actorRole: 'Clinic physician', currentState: 'Follow-up Decision Required', reportVersion: '2', selectedDirection, evidenceReference, directionId: 'SYN-DIR-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setResult(outcome) }
  function verifyT08() { const outcome = evaluateT08Verification({ actorRole: 'Care Coordinator', selectedDirection, ...t08Evidence, verificationId: 'SYN-T08-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setT08Confirmed(true) }
  const displayedState = t08Confirmed ? 'Next Step Confirmed' : result?.stateAfter ?? 'Follow-up Decision Required'
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-04 · COS-604 · human-owned follow-up direction</p><h2>Record a follow-up direction</h2><p>Asha Mehta · SYNTHETIC CASE · acknowledged report SYN-DR-6001 v2</p></div><span className="state-badge">{displayedState}</span></header><div className="screen-grid"><div><WorkflowStatus state={displayedState} owner={t08Confirmed ? 'Care Coordinator · confirmation owner' : 'Synthetic Clinic Physician · clinical direction owner'} next={result?.nextAction ?? 'Select one direction and record its evidence'} /><section className="evidence-panel"><p className="panel-label">Human decision boundary</p><h3>Clinic physician decision</h3><p>ContinuumOS records the selected direction and evidence. It does not recommend, rank or preselect a care direction.</p><fieldset className="direction-options" disabled={Boolean(result)}><legend>Select one approved direction</legend>{['clinic management', 'day-care referral', 'hospital escalation'].map((direction) => <label key={direction}><input checked={selectedDirection === direction} name="direction" type="radio" onChange={() => setSelectedDirection(direction)} />{direction}</label>)}</fieldset><label className="evidence-input">Direction rationale / evidence reference<input value={evidenceReference} onChange={(event) => setEvidenceReference(event.target.value)} placeholder="For example: SYN-DR-6001 v2" disabled={Boolean(result)} /></label>{result ? <div className="status-panel" role="status"><strong>Direction recorded: {selectedDirection}</strong><span>Actor: Synthetic Clinic Physician · report v2 · EVT-11. {result.requiresCoordinatorVerification ? 'Care Coordinator T08 verification is required before the next step is confirmed.' : result.nextAction}</span></div> : <div className="action-group"><button className="primary-action" type="button" onClick={recordDirection}>Record follow-up direction</button><button className="secondary-action" type="button" onClick={() => onException('Current report version requires review')}>Show stale-version safe route</button></div>}</section>{result?.requiresCoordinatorVerification && <section className="evidence-panel t08-panel"><p className="panel-label">Separate operational confirmation</p><h3>Care Coordinator T08 verification</h3><p>This does not change the Clinic physician’s direction. Confirm the authorised operational evidence before recording Next Step Confirmed.</p><div className="t08-grid"><label>Named owner<input disabled={t08Confirmed} value={t08Evidence.owner} onChange={(event) => updateT08('owner', event.target.value)} /></label><label>Timeframe<input disabled={t08Confirmed} value={t08Evidence.timeframe} onChange={(event) => updateT08('timeframe', event.target.value)} /></label><label>Next task<input disabled={t08Confirmed} value={t08Evidence.nextTask} onChange={(event) => updateT08('nextTask', event.target.value)} /></label><label>Applicable communication evidence<input disabled={t08Confirmed} value={t08Evidence.communicationEvidence} onChange={(event) => updateT08('communicationEvidence', event.target.value)} /></label></div>{t08Confirmed ? <div className="status-panel" role="status"><strong>Next Step Confirmed</strong><span>Care Coordinator verification recorded · EVT-16. Direction remains clinic management.</span></div> : <button className="primary-action" type="button" onClick={verifyT08}>Verify T08 evidence and confirm next step</button>}</section>}</div><JourneyRail phase="Human direction" next={result?.nextAction ?? 'A human Clinic physician must choose and evidence the next direction.'} /></div></section>
}

export function App() {
  const [activeScreen, setActiveScreen] = useState<ScreenId>(screenFromHash); const [launchStatus, setLaunchStatus] = useState<'ready' | 'loading'>('ready'); const [authorised, setAuthorised] = useState(false); const [exception, setException] = useState<Extract<ReturnType<typeof resolveSimulatedLaunch>, { kind: 'exception' }> | null>(null); const screen = APPROVED_SCREENS.find((item) => item.id === activeScreen) ?? APPROVED_SCREENS[0]
  const groupedScreens = Array.from(new Set(APPROVED_SCREENS.map((item) => item.group))).map((group) => ({ group, items: APPROVED_SCREENS.filter((item) => item.group === group) }))
  useEffect(() => { const update = () => setActiveScreen(screenFromHash()); window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update) }, [])
  function launch(outcome: 'authorised' | 'unavailable' = 'authorised') { setLaunchStatus('loading'); window.setTimeout(() => { const result = resolveSimulatedLaunch(fixture, outcome); setLaunchStatus('ready'); if (result.kind === 'exception') { setAuthorised(false); setException(result); navigateTo('SCR-07') } else { setAuthorised(true); setException(null); navigateTo('SCR-02') } }, 250) }
  function reset() { setAuthorised(false); setException(null); navigateTo('SCR-01') }
  function returnToLastVerifiedWork(state: string) { setException(null); if (state === 'Clinical Review Pending') navigateTo('SCR-03'); else if (state === 'Referral Created') navigateTo('SCR-05'); else if (state === 'Referral Accepted' || state === 'Next Step Confirmed') navigateTo('SCR-10'); else navigateTo('SCR-02') }
  function showException(condition: string) { setException({ kind: 'exception', condition, owner: 'Diagnostic operations', safeReturn: 'Resolve current evidence, then return to the authorised human workflow.', protectedContextAvailable: false }); navigateTo('SCR-07') }
  return <div className="app-shell"><a className="skip-link" href="#prototype-content">Skip to workspace content</a><header className="topbar"><div className="brand-block"><span aria-hidden="true" className="brand-mark">C</span><div><p className="eyebrow">CONTINUUMOS · SYNTHETIC PORTFOLIO PROTOTYPE</p><h1>Diagnostic closure workspace</h1></div></div><div className="scope-block"><p className="scope-label">Synthetic prototype</p><span>Independent portfolio case · no live patient data</span></div></header><div className="workspace"><nav aria-label="Diagnostic closure workflow" className="screen-nav"><div className="nav-intro"><p className="nav-heading">Care workflow</p><p className="nav-support">Follow the evidence from access to a confirmed next step. Your current task is highlighted.</p></div>{groupedScreens.map(({ group, items }) => <section className="nav-group" key={group}><p>{group}</p><ol>{items.map((item, index) => <li key={item.id}><button aria-current={item.id === activeScreen ? 'step' : undefined} className={item.id === activeScreen ? 'active' : undefined} onClick={() => navigateTo(item.id)} type="button"><span aria-hidden="true" className="nav-step">{group === 'Care workflow' ? index + 1 : '•'}</span><span className="nav-copy"><strong>{item.label}</strong><small>{item.detail}</small></span></button></li>)}</ol></section>)}</nav><main id="prototype-content" tabIndex={-1}>{activeScreen === 'SCR-01' && <Launch status={launchStatus} onLaunch={launch} />}{activeScreen === 'SCR-02' && <Workspace authorised={authorised} onException={() => launch('unavailable')} />}{activeScreen === 'SCR-03' && <ReviewScreen onException={showException} />}{activeScreen === 'SCR-04' && <DirectionScreen onException={showException} />}{activeScreen === 'SCR-05' && <ReferralScreen onException={showException} />}{activeScreen === 'SCR-06' && <ReceivingResponseScreen onException={showException} />}{activeScreen === 'SCR-07' && <ExceptionScreen detail={exception} onReturn={returnToLastVerifiedWork} />}{activeScreen === 'SCR-08' && <AiDraftReviewScreen onReturn={navigateTo} />}{activeScreen === 'SCR-09' && <AuditTraceScreen />}{activeScreen === 'SCR-10' && <NextStepConfirmationScreen onException={showException} />}{!['SCR-01', 'SCR-02', 'SCR-03', 'SCR-04', 'SCR-05', 'SCR-06', 'SCR-07', 'SCR-08', 'SCR-09', 'SCR-10'].includes(activeScreen) && <section className="content-card"><h2>{screen.label}</h2><p>This route is not available in the current prototype.</p></section>}</main></div></div>
}
